const rows = $input.all().map(i => i.json);
const target = rows.find(r => String(r['상태'] || '').trim() === '조사중' && String(r['배치ID'] || '').trim() !== '');
if (!target) return [];
return [{ json: target }];

const item = $input.first().json;
const raw = (item && item.data !== undefined) ? item.data : item;
const text = typeof raw === 'string' ? raw : JSON.stringify(raw);
const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
if (!lines.length) { throw new Error('배치 결과가 비어 있습니다 (results_url 응답을 확인하세요)'); }
const result = JSON.parse(lines[0]);
const blocks = (result.result && result.result.message && result.result.message.content) || [];
const textBlocks = blocks.filter(b => b.type === 'text');
if (!textBlocks.length) { throw new Error('사실조사 응답에 text 블록이 없습니다'); }
const lastText = textBlocks[textBlocks.length - 1].text;

let between = lastText.split('<<<').pop().split('>>>')[0].trim();
between = between.replace(/\r?\n/g, ' ');
const facts = JSON.parse(between);

const factsArr = facts.facts || [];
const sourcesArr = facts.sources || [];
const entitiesArr = facts.entities || [];
const firstEntityFactIds = (entitiesArr[0] && entitiesArr[0].fact_ids) || [];
const passGateA = factsArr.length >= 6 && sourcesArr.length >= 2 && firstEntityFactIds.length >= 1;

const sourceUrls = sourcesArr.map(s => s.url).filter(Boolean).join(', ');
const rowInfo = $('조사중 행 찾기').item.json;

const gateReason = passGateA
  ? '게이트A 통과'
  : ('게이트A 탈락: facts ' + factsArr.length + '/6, sources ' + sourcesArr.length + '/2, entity1 fact_ids ' + firstEntityFactIds.length + '/1');

return [{ json: {
  row_number: rowInfo.row_number,
  facts_json_text: between,
  image_grade: facts.image_grade || '',
  grade_reason: facts.grade_reason || '',
  source_urls: sourceUrls,
  pass_gate_a: passGateA,
  gate_reason: gateReason,
} }];
